/**
 * NFL stadium coordinates - geocoded 2026-10-23 from OSM Nominatim, venue-level.
 *
 * Every row carries the exact query that produced it, so any coordinate can be
 * re-checked against nominatim.openstreetmap.org. This closes the L3 wall where
 * the ESPN venue payload carries a city name but no coordinates, and the
 * nfl-farm `stadium_bearings.json` carried bearings without lat/lon.
 *
 * Generated by the audit-trail script; do not hand-edit a coordinate.
 * Re-geocode instead.
 */

export interface StadiumCoordinates {
  readonly team: string;
  readonly stadium: string;
  readonly city: string;
  readonly state: string;
  readonly lat: number;
  readonly lon: number;
  readonly source: string;
  readonly osmType: string;
  readonly osmId: string;
}

