const R_MILES = 3958.8;

const rad = (deg: number): number => (deg * Math.PI) / 180;

/** Great-circle distance between two teams' stadiums, miles. Both endpoints are
 * venue geocodes, so this is stadium-to-stadium, not city-centre. */
export function travelMiles(fromTeam: string, toTeam: string): number | null {
  const a = STADIUM_COORDINATES[fromTeam];
  const b = STADIUM_COORDINATES[toTeam];
  if (!a || !b) return null;
  const dLat = rad(b.lat - a.lat);
  const dLon = rad(b.lon - a.lon);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2;
  return Math.round(2 * R_MILES * Math.asin(Math.sqrt(h)));
}
